import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import {
  fullPeriodCharge,
  periodEndAfter,
} from "@/lib/billing-period";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { issueInvoice } from "@/server/services/invoicing";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";
import type { OrgId } from "@/types/common";

const logger = createLogger("billing-renewal-job");

/**
 * One pass over every live workspace. Each subscription is handled on its
 * own so one failure never blocks the rest; the subscription row is advanced
 * after each period's invoice, so a rerun at the same instant finds nothing
 * left to do.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listAllLiveSubscriptions();

    for (const subscription of subscriptions) {
      try {
        const changed = await process(subscription, now);
        if (changed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function process(subscription: Subscription, now: Date): Promise<boolean> {
  const nowMs = now.getTime();
  let current = subscription;
  let changed = false;

  if (current.status === "canceled") {
    if (current.cancelAt === null || Date.parse(current.cancelAt) > nowMs) {
      return false;
    }
    current = await endSubscription(current, now);
    changed = true;
  } else if (current.status !== "active") {
    return false;
  }

  while (Date.parse(current.currentPeriodEnd) <= nowMs) {
    const start = new Date(current.currentPeriodEnd);
    const end = periodEndAfter(start, current.interval);
    const periodStart = toIsoTimestamp(start);
    const periodEnd = toIsoTimestamp(end);

    current = await subscriptionRepo.patchSubscription(
      current.orgId as OrgId,
      { currentPeriodStart: periodStart, currentPeriodEnd: periodEnd },
    );
    changed = true;

    if (current.plan !== "free") {
      await issueInvoice({
        orgId: current.orgId as OrgId,
        actorId: null,
        occurredAt: toIsoTimestamp(now),
        amountCents: fullPeriodCharge(
          current.plan,
          current.seats,
          current.interval,
        ),
        periodStart,
        periodEnd,
      });
    }
  }

  return changed;
}

/** Moves a canceled workspace to the free plan as of its cancellation date. */
async function endSubscription(
  subscription: Subscription,
  now: Date,
): Promise<Subscription> {
  const orgId = subscription.orgId as OrgId;
  const start = new Date(subscription.cancelAt as string);

  const updated = await subscriptionRepo.patchSubscription(orgId, {
    plan: "free",
    interval: "monthly",
    status: "active",
    cancelAt: null,
    currentPeriodStart: toIsoTimestamp(start),
    currentPeriodEnd: toIsoTimestamp(periodEndAfter(start, "monthly")),
  });

  await emit("billing.plan_changed", {
    orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(now),
    from: subscription.plan,
    to: "free",
  });

  return updated;
}
