import { getPlanLimits } from "@/config/plan-limits";
import type { BillingInterval, PlanId } from "@/types/billing";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export function monthsIn(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * Same day-of-month and time of day `months` later (UTC); clamped to the
 * target month's last day when it has no such day.
 */
export function addMonthsClamped(from: Date, months: number): Date {
  const total = from.getUTCFullYear() * 12 + from.getUTCMonth() + months;
  const year = Math.floor(total / 12);
  const month = total - year * 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  const result = new Date(from.getTime());
  result.setUTCFullYear(year, month, Math.min(from.getUTCDate(), lastDay));
  return result;
}

export function periodEndAfter(start: Date, interval: BillingInterval): Date {
  return addMonthsClamped(start, monthsIn(interval));
}

/** Full charge for one period of `plan`, in cents. */
export function fullPeriodCharge(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
    getPlanLimits(plan).priceCentsPerSeatMonthly * seats * monthsIn(interval)
  );
}

/** `amountCents` scaled by days left over days in the period, rounded down. */
export function prorate(
  amountCents: number,
  periodStart: Date,
  periodEnd: Date,
  now: Date,
): number {
  const remainingMs = periodEnd.getTime() - now.getTime();
  if (remainingMs <= 0 || amountCents <= 0) return 0;

  const daysLeft = Math.ceil(remainingMs / MS_PER_DAY);
  const daysInPeriod = Math.max(
    1,
    Math.round((periodEnd.getTime() - periodStart.getTime()) / MS_PER_DAY),
  );
  const scaled = amountCents * daysLeft;
  return (scaled - (scaled % daysInPeriod)) / daysInPeriod;
}
